// ---- Custom pickers (replace the browser/native <select> and <input type="date"> dialogs) ----
function PickerSheet({title,onClose,children}){
  useEffect(()=>{const k=e=>{if(e.key==='Escape')onClose();};window.addEventListener('keydown',k);return()=>window.removeEventListener('keydown',k);},[onClose]);
  return createPortal(<div className="picker-scrim" onMouseDown={e=>{if(e.target===e.currentTarget){e.preventDefault();onClose();}}}><div className="picker-sheet" role="dialog" aria-modal="true" aria-label={title}><div className="picker-grab"/><div className="picker-head"><h3>{title}</h3><button type="button" className="icon-btn" onMouseDown={e=>e.preventDefault()} onClick={onClose} aria-label="Close"><X size={17}/></button></div>{children}</div></div>,document.body);
}
function SelectField({id,label,value,defaultValue,options,onChange,className='capsule-input',compact=false,icon=null}){
  const [open,setOpen]=useState(false);
  const [inner,setInner]=useState(defaultValue);
  const val=value!==undefined?value:inner;
  let items=options.map(o=>typeof o==='string'?{value:o,label:o}:o);
  if(val!==undefined&&val!==''&&!items.some(o=>o.value===val))items=[{value:val,label:String(val)},...items];
  const current=items.find(o=>o.value===val)||items[0];
  const listRef=useRef(null);
  useEffect(()=>{if(open)requestAnimationFrame(()=>listRef.current?.querySelector('.on')?.scrollIntoView({block:'center'}));},[open]);
  const keepFocus=compact?{onMouseDown:e=>e.preventDefault()}:{};
  return <>
    <button type="button" id={id} className={compact?'picker-btn compact':`${className} picker-btn`} {...keepFocus} onClick={()=>setOpen(true)} aria-haspopup="dialog" aria-expanded={open} aria-label={compact?label:undefined}>{icon}<span>{current?.label}</span><ChevronDown size={compact?13:15}/></button>
    {open&&<PickerSheet title={label} onClose={()=>setOpen(false)}><div className="picker-list" ref={listRef} role="listbox">{items.map(o=><button type="button" role="option" aria-selected={o.value===val} key={String(o.value)} className={`picker-opt ${o.value===val?'on':''}`} onMouseDown={e=>e.preventDefault()} onClick={()=>{setInner(o.value);onChange(o.value);setOpen(false);}}><span style={o.style}>{o.label}</span>{o.value===val&&<Check size={17}/>}</button>)}</div></PickerSheet>}
  </>;
}
function DateField({id,label,value,onChange}){
  const [open,setOpen]=useState(false);
  const parse=v=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(v||'');return m?new Date(+m[1],+m[2]-1,+m[3]):null;};
  const fmt=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const sel=parse(value);
  const [view,setView]=useState(()=>sel||new Date());
  useEffect(()=>{if(open)setView(parse(value)||new Date());},[open]);
  const y=view.getFullYear(),m=view.getMonth();
  const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();
  const cells=[...Array(first).fill(null),...Array.from({length:days},(_,i)=>i+1)];
  const todayStr=fmt(new Date());
  const text=sel?sel.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'Select a date';
  return <>
    <button type="button" id={id} className="capsule-input picker-btn" onClick={()=>setOpen(true)} aria-haspopup="dialog" aria-expanded={open}><CalendarClock size={15}/><span className={sel?'':'placeholder'}>{text}</span><ChevronDown size={15}/></button>
    {open&&<PickerSheet title={label} onClose={()=>setOpen(false)}>
      <div className="cal-head"><button type="button" className="icon-btn" aria-label="Previous month" onClick={()=>setView(new Date(y,m-1,1))}><ArrowLeft size={16}/></button><strong>{view.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><button type="button" className="icon-btn" aria-label="Next month" onClick={()=>setView(new Date(y,m+1,1))}><ArrowRight size={16}/></button></div>
      <div className="cal-grid cal-dow">{['S','M','T','W','T','F','S'].map((d,i)=><span key={i}>{d}</span>)}</div>
      <div className="cal-grid">{cells.map((d,i)=>{if(!d)return <span key={i}/>;const ds=fmt(new Date(y,m,d));return <button type="button" key={i} className={`cal-day ${ds===value?'on':''} ${ds===todayStr?'today':''}`} onClick={()=>{onChange(ds);setOpen(false);}}>{d}</button>;})}</div>
      <div className="picker-actions"><button type="button" className="ghost-btn" onClick={()=>{onChange('');setOpen(false);}}>Clear</button><button type="button" className="ghost-btn" onClick={()=>{onChange(todayStr);setOpen(false);}}>Today</button></div>
    </PickerSheet>}
  </>;
}
