  async function schedulePublish(){if(!destinations.blogger){setToast('Choose Blogger as the publishing destination');return;}const date=new Date(scheduleAt.replace(' ','T'));if(!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(scheduleAt)||Number.isNaN(date.getTime())||date.getTime()<Date.now()+60_000){setToast('Choose a future time at least one minute from now');return;}setScheduleBusy(true);try{const siteIds={blogger:selectedBlogId||connectedSites.find(x=>x.provider==='blogger')?.id};const data=await apiFetch('/api/publish/schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:response,destinations,siteIds,scheduledAt:date.toISOString()})});const p={...response,status:'Scheduled',scheduledAt:data.scheduledAt||date.toISOString(),scheduleId:data.id,updatedAt:now()};setActive(p);setResponse(p);await saveProject(p);setShowPublish(false);setScheduleAt('');setToast('Article scheduled successfully');setPage('workspace');}catch(e){let message='We couldn’t schedule this article just yet. Your draft is safe in your workspace. Please try again in a moment.';if(e.code==='USER_LIMIT'||e.status===429){message='You’ve reached your active schedule limit. Your article is safe and hasn’t been scheduled. Publish or cancel an existing scheduled article, then try again.';}else if(e.code==='GLOBAL_LIMIT'||e.status===503){message='Wyticle’s publishing queue is having a busy moment. Your article is safe and nothing has been scheduled yet. Please try again in a few minutes, or choose a later time.';}else if(/future time|90 days|valid future|Choose a future/i.test(e.message||'')){message=e.message;}else if(/connect|authorization|credentials|Blogger/i.test(e.message||'')){message=`We couldn’t confirm your publishing connection. Your article is safe. ${e.message}`;}else if(/too large/i.test(e.message||'')){message='This article is a little too large to schedule as-is. Try using image URLs instead of embedded image files, then schedule it again.';}setToast(message);}finally{setScheduleBusy(false);}}
