  // After PIN/OTP (or a 3-D Secure return) ask the backend to confirm with Flutterwave; credits are only added server-side.
  async function finishPayment(ref){
    setPayStep('wait');setPayMsg('Confirming your payment…');
    for(let i=0;i<8;i++){
      try{const data=await apiFetch('/api/billing/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reference:ref})});
        if(data.status==='succeeded'){
          localStorage.removeItem('wryte-pending-payment');
          try{await refreshAccount();}catch{await persistSettings({...settings,credits:Number(data.credits??settings.credits),freeGenerations:Number(settings.freeGenerations||0)});}
          setFormError('');setToast(data.addedCredits>0?`Payment successful · ${Number(data.addedCredits).toLocaleString()} credits added`:'This payment was already credited. Your balance is up to date.');resetPay();return;
        }
        if(data.status==='failed'){localStorage.removeItem('wryte-pending-payment');setToast(data.message||'Payment failed. You can try again.');resetPay();return;}
        if(data.state?.step==='pin'||data.state?.step==='otp'){handlePayState(data.state,ref);return;}
      }catch(e){if(e.status&&e.status<500){setToast(e.message);resetPay();return;}}
      await sleep(3000);
    }
    setPayStep('pick');setToast('Payment is still pending. Tap “Verify pending payment” in a moment.');
  }
  function handlePayState(st,ref){
    if(!st||st.step==='wait'||st.step==='done'){finishPayment(ref);return;}
    if(st.step==='pin'){setPayStep('pin');setPayMsg(st.message||'Enter your 4-digit card PIN.');return;}
    if(st.step==='otp'){setPayStep('otp');setPayMsg(st.message||'Enter the OTP your bank sent you.');return;}
    if(st.step==='redirect'&&st.url){setPayStep('wait');setPayMsg('Complete the bank verification, then return to the app.');if(Capacitor.isNativePlatform())Browser.open({url:st.url});else window.location.href=st.url;return;}
    localStorage.removeItem('wryte-pending-payment');setToast(st.message||'Payment failed. You can try again.');resetPay();
  }
  async function payWithCard(){
    const number=card.number.replace(/\D/g,'');const [mm,yy]=card.exp.split('/').map(x=>(x||'').trim());const cvv=card.cvv.replace(/\D/g,'');
    if(number.length<12||!mm||!yy||cvv.length<3){setToast('Enter your card number, expiry (MM/YY) and security code.');return;}
    setBillingBusy(true);
    try{
      const data=await apiFetch('/api/billing/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({packId:payPack.id,card:{number,expiryMonth:mm,expiryYear:yy,cvv},returnUrl:Capacitor.isNativePlatform()?'ai.wryte.app://auth-callback':window.location.origin})});
      localStorage.setItem('wryte-pending-payment',data.reference);setPayRef(data.reference);
      handlePayState(data.state,data.reference);
    }catch(e){setToast(e.message||'Unable to start payment');}
    finally{setCard({number:'',exp:'',cvv:''});setBillingBusy(false);} // never keep card details in memory longer than needed
  }
