  async function saveDriveFolder(){try{const data=await apiFetch('/api/drive/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({folderId:settings.driveFolderId||''})});setSettings(v=>({...v,driveFolderId:data.folderId||'',driveConnected:Boolean(data.connected)}));await persistSettings({...settings,driveFolderId:data.folderId||'',driveConnected:Boolean(data.connected)});setModal('');setToast(data.configured?`Drive folder connected${data.folderName?`: ${data.folderName}`:''}. Published articles will also be saved as TXT files.`:'Drive TXT export disabled');}catch(e){setToast(e.message||'Unable to save Google Drive settings');}}
  async function loadDriveFiles(){
    if(!user||!settings.driveFolderId){setDriveFiles([]);return;}
    setDriveFilesBusy(true);try{const data=await apiFetch('/api/drive/files');setDriveFiles(data.files||[]);}catch(e){setToast(e.message||'Could not load Drive projects');}finally{setDriveFilesBusy(false);}
  }
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  async function downloadFinalProject(project=response){if(!project){setToast('Open a project before downloading');return;}setDownloadProject(project);setModal('download-format');}
  function projectHtml(project){const title=String(project.title||'wyticle-project');const meta=project.seo||{};return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(meta.title||title)}</title><meta name="description" content="${escapeHtml(meta.description||'')}"><style>@page{size:A4;margin:22mm}body{max-width:780px;margin:35px auto;padding:0 24px;font:12pt/1.65 Georgia,serif;color:#202020}h1{font-size:24pt;line-height:1.2;margin:0 0 20px}h2{font-size:17pt;margin-top:25px}h3{font-size:13pt;margin-top:18px}p{margin:0 0 12px}img{max-width:100%;height:auto}li{margin-bottom:6px}.document-meta{font-size:10pt;color:#555;margin-bottom:24px}</style></head><body><h1>${escapeHtml(title)}</h1>${project.documentType==='article'&&/^(data:image\/|https?:)/i.test(project.featuredImage||'')?`<img src="${escapeHtml(project.featuredImage)}" alt="Featured image">`:''}${sanitizeHtml(project.body||'')}</body></html>`;}
  function documentBlocks(project){const parser=new DOMParser();const doc=parser.parseFromString(project.body||`<p>${escapeHtml(project.plainText||'')}</p>`,'text/html');const blocks=[];const walk=(node)=>{for(const el of Array.from(node.children||[])){const tag=el.tagName.toLowerCase();const text=(el.innerText||el.textContent||'').trim();if(['h1','h2','h3'].includes(tag)&&text)blocks.push({type:'heading',level:tag==='h1'?1:tag==='h2'?2:3,text});else if(tag==='p'&&text)blocks.push({type:'paragraph',text});else if(tag==='li'&&text)blocks.push({type:'bullet',text});else if(tag==='ul'||tag==='ol')walk(el);else if(tag==='blockquote'&&text)blocks.push({type:'quote',text});else if(tag==='table')for(const row of Array.from(el.querySelectorAll('tr'))){const cells=Array.from(row.querySelectorAll('th,td')).map(c=>c.textContent.trim()).filter(Boolean);if(cells.length)blocks.push({type:'paragraph',text:cells.join('  |  ')});}else if(text&&!['figure','img','div','span'].includes(tag))blocks.push({type:'paragraph',text});else if(['div','section','article','figure'].includes(tag))walk(el);}};walk(doc.body);if(!blocks.length)blocks.push({type:'paragraph',text:project.plainText||''});return blocks;}
  async function downloadProjectFormat(project,format){if(!project)return;setModal('');const title=String(project.title||'wyticle-project').replace(/[\\/:*?"<>|\r\n]+/g,'-').trim().slice(0,90)||'wyticle-project';try{let blob,name;
    if(format==='txt'){const lines=[project.title||'Untitled',project.brief?.sender?`From: ${project.brief.sender}`:'',project.brief?.recipient?`To: ${project.brief.recipient}`:'',project.brief?.recipientAddress?`Recipient address: ${project.brief.recipientAddress}`:'',project.brief?.senderAddress?`Sender address: ${project.brief.senderAddress}`:'',project.brief?.organization?`Organization: ${project.brief.organization}`:'',project.brief?.date?`Date: ${project.brief.date}`:'','',project.plainText||stripHtml(project.body||'')].filter((v,i)=>v!==''||i>2);blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});name=`${title}.txt`;
    }else if(format==='html'){blob=new Blob([projectHtml(project)],{type:'text/html;charset=utf-8'});name=`${title}.html`;
    }else if(format==='pdf'){const pdf=new jsPDF({unit:'pt',format:'a4'});const left=54,right=54,top=58,bottom=54,width=pdf.internal.pageSize.getWidth()-left-right;let y=top;pdf.setFont('times','bold');pdf.setFontSize(20);const titleLines=pdf.splitTextToSize(project.title||'Untitled document',width);titleLines.forEach(line=>{if(y>pdf.internal.pageSize.getHeight()-bottom){pdf.addPage();y=top;}pdf.text(line,left,y);y+=25;});y+=8;pdf.setFont('times','normal');for(const b of documentBlocks(project)){const heading=b.type==='heading';pdf.setFont('times',heading?'bold':'normal');pdf.setFontSize(heading?(b.level===1?17:b.level===2?14:12):11);const text=b.type==='bullet'?`-  ${b.text}`:b.text;const lines=pdf.splitTextToSize(text,width-(b.type==='bullet'?10:0));const lineHeight=heading?19:16;if(y+lines.length*lineHeight>pdf.internal.pageSize.getHeight()-bottom){pdf.addPage();y=top;}pdf.text(lines,left+(b.type==='bullet'?8:0),y);y+=lines.length*lineHeight+(heading?8:5);}blob=pdf.output('blob');name=`${title}.pdf`;
    }else if(format==='docx'){const children=[new Paragraph({text:project.title||'Untitled document',heading:HeadingLevel.TITLE,spacing:{after:300}})];if(project.brief?.sender||project.brief?.recipient||project.brief?.senderAddress||project.brief?.recipientAddress||project.brief?.organization||project.brief?.date){for(const [label,value] of [['From',project.brief?.sender],['Sender address',project.brief?.senderAddress],['To',project.brief?.recipient],['Recipient address',project.brief?.recipientAddress],['Organization',project.brief?.organization],['Date',project.brief?.date]])if(value)children.push(new Paragraph({children:[new TextRun({text:`${label}: `,bold:true}),new TextRun(value)],spacing:{after:80}}));children.push(new Paragraph({text:'',spacing:{after:160}}));}for(const b of documentBlocks(project)){if(b.type==='heading')children.push(new Paragraph({text:b.text,heading:b.level===1?HeadingLevel.HEADING_1:b.level===2?HeadingLevel.HEADING_2:HeadingLevel.HEADING_3,spacing:{before:220,after:100},keepNext:true}));else if(b.type==='bullet')children.push(new Paragraph({text:b.text,bullet:{indent:360},spacing:{after:100}}));else children.push(new Paragraph({text:b.text,spacing:{after:160},alignment:AlignmentType.JUSTIFIED}));}const doc=new Document({sections:[{properties:{page:{size:{width:11906,height:16838},margin:{top:1134,right:1134,bottom:1134,left:1134}}},children}]});blob=await Packer.toBlob(doc);name=`${title}.docx`;
    }else throw new Error('Unsupported download format');
    if(Capacitor.isNativePlatform()){const reader=new FileReader();const base64=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});const saved=await Filesystem.writeFile({path:name,data:base64,directory:Directory.Cache,recursive:true});await Share.share({title:`Download ${title}`,text:`${project.documentType||'Project'} export from Wyticle AI`,url:saved.uri,dialogTitle:'Save or share your project'});setToast(`${name} is ready. Choose Save or another destination.`);}else{downloadBlob(blob,name);setToast(`${name} downloaded successfully.`);}
  }catch(e){console.error('Project export failed:',e);setToast(`Could not create ${format.toUpperCase()} export: ${e.message||'Please try another format.'}`);}}
  async function downloadDriveFile(file){
    if(!file?.id)return;setDriveDownloadBusy(file.id);
    try{
      const headers=await tokenHeaders();const r=await fetch(`${API_BASE}/api/drive/files/${encodeURIComponent(file.id)}/download`,{headers});
      if(!r.ok){const data=await r.json().catch(()=>({}));throw new Error(data.error||'Could not download this Drive project.');}
      const blob=await r.blob();const name=file.name||'wyticle-article.txt';
      if(Capacitor.isNativePlatform()){
        const reader=new FileReader();const base64=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});
        const saved=await Filesystem.writeFile({path:name,data:base64,directory:Directory.Cache,recursive:true});await Share.share({title:name,text:'TXT project downloaded from Google Drive',url:saved.uri,dialogTitle:'Save or share TXT project'});
      }else downloadBlob(blob,name);
      setToast(`Downloaded ${name}`);
    }catch(e){setToast(e.message||'Unable to download this Drive file');}finally{setDriveDownloadBusy('');}
  }
  function logout(){signedInRef.current=false;if(auth)auth.signOut().catch(()=>{});if(Capacitor.isNativePlatform())FirebaseAuthentication.signOut().catch(()=>{});setUser(null);setFirebaseUser(null);setConnectedSites([]);setPage('signin');setMenuOpen(false);}
