// Google Identity Services fallback: signs in without a redirect or Firebase's cross-site iframe, so it still works in browsers that block third-party storage.
// The Web OAuth client below must list this site's origin under "Authorized JavaScript origins" (Google Cloud Console -> APIs & Services -> Credentials).
const WEB_GOOGLE_CLIENT_ID = import.meta.env.VITE_GOOGLE_WEB_CLIENT_ID || '589252246114-pdlhe9mbu5u80p554039bdp4pp1e3ada.apps.googleusercontent.com';
function loadGoogleIdentity(){
  return new Promise((resolve,reject)=>{
    const ready=()=>window.google?.accounts?.oauth2?resolve(window.google.accounts.oauth2):reject(new Error('Google sign-in did not load.'));
    if(window.google?.accounts?.oauth2)return resolve(window.google.accounts.oauth2);
    const fail=()=>reject(new Error('Could not load Google sign-in. Check your connection or turn off your ad blocker for this site.'));
    const existing=document.querySelector('script[data-gis]');
    if(existing){existing.addEventListener('load',ready);existing.addEventListener('error',fail);return;}
    const sc=document.createElement('script');sc.src='https://accounts.google.com/gsi/client';sc.async=true;sc.defer=true;sc.dataset.gis='1';sc.onload=ready;sc.onerror=fail;document.head.appendChild(sc);
  });
}
function googleAccessToken(){
  return loadGoogleIdentity().then(oauth2=>new Promise((resolve,reject)=>{
    const client=oauth2.initTokenClient({client_id:WEB_GOOGLE_CLIENT_ID,scope:'openid email profile',prompt:'select_account',
      callback:r=>{if(r?.access_token)resolve(r.access_token);else reject(Object.assign(new Error(r?.error_description||r?.error||'Google sign-in failed.'),{code:`gis/${r?.error||'failed'}`}));},
      error_callback:e=>reject(Object.assign(new Error(e?.message||e?.type||'Google sign-in failed.'),{code:`gis/${e?.type||'failed'}`}))});
    client.requestAccessToken();
  }));
}
if(typeof window!=='undefined'&&!Capacitor.isNativePlatform())setTimeout(()=>loadGoogleIdentity().catch(()=>{}),1200); // preload so the click that follows still counts as a user gesture
function isEmbeddedBrowser(){const ua=navigator.userAgent||'';return /FBAN|FBAV|Instagram|Line\/|MicroMessenger|Twitter|Snapchat|; wv\)|GSA\//i.test(ua);}
function isStandalonePwa(){try{return Boolean(window.matchMedia?.('(display-mode: standalone)')?.matches||window.navigator.standalone);}catch{return false;}}
function friendlyAuthError(error){
  const code=String(error?.code||'');const msg=String(error?.message||'');const text=`${code} ${msg}`;
  if(code==='gis/popup_failed_to_open')return 'Your browser blocked the Google sign-in window. Allow pop-ups for this site and tap Continue with Google again.';
  if(code==='gis/popup_closed')return `Sign-in was cancelled. If Google showed an "origin_mismatch" error, add ${window.location.origin} under Authorized JavaScript origins for the Web OAuth client in Google Cloud Console (APIs & Services, Credentials), then try again.`;
  if(msg.includes('28444')||/developer console is not set up/i.test(msg))return 'Google sign-in is not set up for this APK yet. Add this APK\'s SHA-1 and SHA-256 in Firebase, download a fresh google-services.json, and rebuild.';
  if(/popup-closed|cancelled|canceled|user.?cancel|12501|\b-5\b/i.test(text))return 'Sign-in was cancelled. You can try again whenever you are ready.';
  if(/network|timeout|\b7\b.*network|unavailable/i.test(text)&&!/play.?services/i.test(text))return 'Google sign-in could not connect. Check your internet and try again.';
  if(/play.?services|SERVICE_MISSING|SERVICE_DISABLED|SERVICE_VERSION_UPDATE_REQUIRED/i.test(text))return 'Google Play services is missing or out of date on this device. Update it from the Play Store and try again.';
  if(code.includes('unauthorized-domain'))return 'This website is not yet approved for Firebase sign-in. Add its domain in Firebase Authentication settings.';
  if(code.includes('operation-not-allowed'))return 'Google sign-in is not enabled for this app. Enable the Google provider in Firebase Authentication.';
  if(code.includes('account-exists-with-different-credential'))return 'An account with this email already exists using a different sign-in method.';
  if(code.includes('user-disabled'))return 'This account has been disabled. Contact support if you think this is a mistake.';
  if(code.includes('too-many-requests'))return 'Too many sign-in attempts. Please wait a few minutes and try again.';
  if(code.includes('web-storage-unsupported')||code.includes('operation-not-supported'))return 'Your browser is blocking storage needed for sign-in. Allow cookies/site data for this site, or try another browser.';
  if(/developer_error|DEVELOPER_ERROR|\b10\b/.test(text))return 'Google sign-in needs the Android app SHA-1/SHA-256 fingerprints and matching OAuth setup in Firebase.';
  if(/invalid-api-key|api-key-not-valid/i.test(text))return 'The Firebase web configuration is invalid. Check the API key in your Firebase settings.';
  return error?.message&&!/^Firebase: /.test(error.message)?error.message:'Unable to sign in right now. Please try again.';
}
function stripHtml(html=''){const doc=new DOMParser().parseFromString(String(html),'text/html');return (doc.body.textContent||'').trim();}
// Allow-list sanitizer for AI-generated / user-edited article HTML (DOMParser documents are inert: no scripts or onerror handlers run).
const SAFE_TAGS=new Set(['A','P','BR','H1','H2','H3','H4','H5','H6','UL','OL','LI','STRONG','B','EM','I','U','S','BLOCKQUOTE','PRE','CODE','HR','IMG','FIGURE','FIGCAPTION','TABLE','THEAD','TBODY','TR','TH','TD','SPAN','DIV','SECTION','ARTICLE','IFRAME','SUP','SUB','MARK']);
function sanitizeHtml(html=''){
  const doc=new DOMParser().parseFromString(String(html),'text/html');
  const walk=(node)=>{[...node.children].forEach(el=>{
    if(!SAFE_TAGS.has(el.tagName)){el.remove();return;}
    [...el.attributes].forEach(a=>{const n=a.name.toLowerCase(),v=a.value.trim();
      const ok=(el.tagName==='A'&&(n==='href'||n==='title'||n==='target'||n==='rel'))||(el.tagName==='IMG'&&(n==='src'||n==='alt'||n==='title'||n==='width'||n==='height'||n==='loading'))||(el.tagName==='IFRAME'&&(n==='src'||n==='title'||n==='allowfullscreen'||n==='loading'))||n==='class'||n==='id'||n==='style'&&!/expression|url\(|javascript:/i.test(v)||(['TD','TH'].includes(el.tagName)&&(n==='colspan'||n==='rowspan'));
      if(!ok||n.startsWith('on'))el.removeAttribute(a.name);
      else if((n==='href'||n==='src')&&!(el.tagName==='IMG'&&/^data:image\/(png|jpe?g|webp|gif);base64,/i.test(v))&&!/^(https?:|mailto:|#|\/)/i.test(v))el.removeAttribute(a.name);});
    if(el.tagName==='IFRAME'&&!/^https:\/\/(www\.youtube-nocookie\.com\/embed\/|player\.vimeo\.com\/video\/)/i.test(el.getAttribute('src')||'')){el.remove();return;}
    if(el.tagName==='A'&&el.getAttribute('target')==='_blank')el.setAttribute('rel','noopener noreferrer');
    walk(el);});};
  walk(doc.body);return doc.body.innerHTML;
}
class ErrorBoundary extends React.Component{
  constructor(p){super(p);this.state={error:null};}
  static getDerivedStateFromError(error){return {error};}
  componentDidCatch(error,info){console.error('Wyticle crashed:',error,info?.componentStack);}
  render(){if(!this.state.error)return this.props.children;return <div style={{minHeight:'100vh',display:'grid',placeItems:'center',padding:24,background:'#080808',color:'#fff',fontFamily:'system-ui,sans-serif',textAlign:'center'}}><div><h2 style={{marginBottom:8}}>Something went wrong</h2><p style={{opacity:.7,marginBottom:16}}>Your saved articles are safe on this device.</p><button style={{padding:'12px 20px',borderRadius:12,border:0,fontWeight:700}} onClick={()=>location.reload()}>Reload Wyticle</button></div></div>;}
}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function slugify(s=''){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80);}

createRoot(document.getElementById('root')).render(<ErrorBoundary><App/></ErrorBoundary>);
